.darma-loader-darma-b14-pinball-bounce { --accent: var(--loader-color, #f97316); --accent-2: var(--loader-secondary-color, #22d3ee); width: calc(var(--loader-size, 124px) * .68); height: var(--loader-size, 124px); position: relative; overflow: hidden; border-radius: 10% 10% 4px 4px; background: linear-gradient(#1e293b, #0b1220); box-shadow: inset 0 0 0 2px #334155; }
.darma-loader-darma-b14-pinball-bounce::before { content: ''; position: absolute; bottom: 8%; left: 12%; width: 34%; height: 6%; border-radius: 999px; transform-origin: left center; background: var(--accent-2); animation: darma-loader-darma-b14-pinball-bounce-flip-left calc(var(--loader-speed, 1s) * 2.2) ease-out infinite; }
.darma-loader-darma-b14-pinball-bounce::after { content: ''; position: absolute; bottom: 8%; right: 12%; width: 34%; height: 6%; border-radius: 999px; transform-origin: right center; background: var(--accent-2); animation: darma-loader-darma-b14-pinball-bounce-flip-right calc(var(--loader-speed, 1s) * 2.2) ease-out infinite; }
.darma-loader-darma-b14-pinball-bounce span { position: absolute; width: 24%; height: calc(var(--loader-size, 124px) * .163); border-radius: 50%; background: radial-gradient(circle at 36% 32%, color-mix(in srgb, #fff 44%, var(--accent)), var(--accent)); animation: darma-loader-darma-b14-pinball-bounce-bumper calc(var(--loader-speed, 1s) * 2.2) ease-out infinite; }
.darma-loader-darma-b14-pinball-bounce span:nth-child(1) { top: 14%; left: 10%; }
.darma-loader-darma-b14-pinball-bounce span:nth-child(2) { top: 32%; right: 10%; animation-delay: calc(var(--loader-speed, 1s) * .48); }
.darma-loader-darma-b14-pinball-bounce .darma-loader-darma-b14-pinball-bounce__ball { position: absolute; width: 15%; height: calc(var(--loader-size, 124px) * .102); border-radius: 50%; background: radial-gradient(circle at 34% 30%, #fff, #94a3b8); animation: darma-loader-darma-b14-pinball-bounce-pinball calc(var(--loader-speed, 1s) * 2.2) ease-in-out infinite; }
@keyframes darma-loader-darma-b14-pinball-bounce-pinball { 0% { left: 42%; top: 76%; } 22% { left: 14%; top: 20%; } 44% { left: 64%; top: 38%; } 64% { left: 24%; top: 58%; } 82% { left: 60%; top: 74%; } 100% { left: 42%; top: 76%; } }
@keyframes darma-loader-darma-b14-pinball-bounce-bumper { 0%, 16% { transform: scale(1); box-shadow: 0 0 0 0 transparent; } 24% { transform: scale(1.14); box-shadow: 0 0 calc(var(--loader-size, 124px) * .08) var(--accent); } 38%, 100% { transform: scale(1); box-shadow: 0 0 0 0 transparent; } }
@keyframes darma-loader-darma-b14-pinball-bounce-flip-left { 0%, 74% { transform: rotate(24deg); } 84% { transform: rotate(-16deg); } 94%, 100% { transform: rotate(24deg); } }
@keyframes darma-loader-darma-b14-pinball-bounce-flip-right { 0%, 74% { transform: rotate(-24deg); } 84% { transform: rotate(16deg); } 94%, 100% { transform: rotate(-24deg); } }

